1	// contractlab —— 可热更新的本地接口场景服务
2	//
3	// 运行环境：Node.js 24（内置 TypeScript 类型擦除，可直接 `node app.ts`），
4	// 无任何外部运行依赖。
5	//
6	// 行为约定（详见 README.md）：
7	// - 业务接口由“方法 + 绝对路径”唯一标识，查询串不参与匹配，不支持路径模板；
8	// - 请求被完整接收后，才按当前配置匹配接口并同步“预留”响应序列的下一项，
9	//   序列耗尽后持续返回末项；预留之后客户端断开，仍计为一次消费；
10	// - POST /__contractlab/reload 重新读取同一配置文件：新配置全部有效时才
11	//   原子替换全部接口、重置全部序列并递增版本号；失败时现状不变；
12	// - 在途请求持有预留时的旧响应快照（状态码/响应头/正文/延迟/版本），
13	//   完成时不会推进新序列；
14	// - POST 接口可附加可选的 requestBody 正文结构规则：请求完整接收后先校验
15	//   媒体类型与 JSON 结构，不符时返回 400 差异报告，不发送场景响应、不消费序列；
16	//   校验通过才按“完整接收”顺序预留响应项。
17	// - 管理入口 GET /__contractlab/requests 查询本次进程内的请求记录（一致快照、
18	//   不推进序列），POST /__contractlab/requests/clear 清空记录；记录只存在内存中，
19	//   管理范围（/__contractlab 本身及 /__contractlab/ 前缀）的请求一律不记录。
20	// - compare 子命令：离线比较旧、新两份场景文件，判断沿用旧接口约定的客户端
21	//   是否仍能调用新版；报告写 stdout，不启动监听、不修改文件。
22	// - import 子命令：读取本地 OpenAPI 3.0 JSON 与现有场景配置，按“方法 + 字面
23	//   路径”选择文档操作，仅用操作 requestBody 转换出的正文规则替换各接口的
24	//   requestBody（保留接口顺序与 responses），新场景 JSON 写 stdout。
25	// - verify 子命令：离线批量请求校验。读取 GET /__contractlab/requests 的完整
26	//   JSON 快照与一份场景配置，按输入顺序保留原编号逐条重新判定（仅依据记录中的
27	//   原始请求重新计算，不信任原版本、匹配/校验结论、计划响应与发送状态）；
28	//   报告写 stdout，不监听、不发送请求、不修改文件。
29	
30	import http from 'node:http';
31	import { readFile } from 'node:fs/promises';
32	import path from 'node:path';
33	
34	const APP_NAME = 'contractlab';
35	
36	// 管理入口（保留前缀，业务接口不得使用）
37	const ADMIN_PREFIX = '/__contractlab/';
38	const ADMIN_BASE = '/__contractlab';
39	const HEALTH_PATH = '/__contractlab/health';
40	const RELOAD_PATH = '/__contractlab/reload';
41	const REQUESTS_PATH = '/__contractlab/requests';
42	const REQUESTS_CLEAR_PATH = '/__contractlab/requests/clear';
43	
44	// 每个业务响应都携带当前配置版本
45	const VERSION_HEADER = 'X-Contractlab-Version';
46	
47	// 请求体上限（本机工具的防误操作保护，超出直接 413，不触碰任何序列）
48	const MAX_BODY_BYTES = 100 * 1024 * 1024;
49	
50	// 由服务器管理、业务配置不得覆盖的“传输头”（大小写不敏感）
51	const BLOCKED_HEADERS = new Set([
52	  'connection',
53	  'keep-alive',
54	  'content-length',
55	  'transfer-encoding',
56	]);
57	
58	// RFC 7230 token：合法的 HTTP 头名称字符
59	const HEADER_NAME_RE = /^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/;
60	
61	type HttpMethod = 'GET' | 'POST';
62	
63	// ---------------------------------------------------------------------------
64	// 请求正文结构规则（endpoints[].requestBody，仅 POST）
65	// ---------------------------------------------------------------------------
66	//
67	// 规则格式（JSON 对象，未知字段一律拒绝）：
68	//   { "type": "object", "fields": { "<名>": <字段规则>, ... }, "additionalProperties": false }
69	//   { "type": "array", "items": <规则> }
70	//   { "type": "string" | "number" | "integer" | "boolean" | "null" }
71	// 字段规则 = 任意规则 + 可选 "required": true（缺省为可缺省）；
72	// object 的 fields / additionalProperties 可省略（默认无字段声明、拒绝未声明字段）；
73	// array 必须声明 items。
74	
75	type ScalarKind = 'string' | 'number' | 'integer' | 'boolean' | 'null';
76	
77	type BodyRule =
78	  | {
79	      readonly kind: 'object';
80	      readonly fields: ReadonlyMap<string, FieldRule>;
81	      readonly additionalProperties: boolean;
82	    }
83	  | { readonly kind: 'array'; readonly items: BodyRule }
84	  | { readonly kind: ScalarKind };
85	
86	interface FieldRule {
87	  readonly rule: BodyRule;
88	  readonly required: boolean;
89	}
90	
91	interface ResponseSpec {
92	  readonly status: number;
93	  readonly headers: { readonly [name: string]: string };
94	  readonly body: string;
95	  readonly delay: number;
96	}
97	
98	interface EndpointSpec {
99	  readonly method: HttpMethod;
100	  readonly path: string;
101	  readonly responses: readonly ResponseSpec[];
102	  readonly bodyRule: BodyRule | undefined;
103	}
104	
105	interface LiveEndpoint {
106	  readonly key: string;
107	  readonly responses: readonly ResponseSpec[];
108	  readonly bodyRule: BodyRule | undefined;
109	  // 下一个待预留位置；到达末项后停在末项（持续复用）
110	  cursor: number;
111	}
112	
113	interface LiveState {
114	  readonly version: number;
115	  readonly endpoints: ReadonlyMap<string, LiveEndpoint>;
116	}
117	
118	interface ReloadResult {
119	  ok: boolean;
120	  version: number;
121	  error?: string;
122	}
123	
124	class ConfigError extends Error {
125	  constructor(message: string) {
126	    super(message);
127	    this.name = 'ConfigError';
128	  }
129	}
130	
131	// ---------------------------------------------------------------------------
132	// 配置校验
133	// ---------------------------------------------------------------------------
134	
135	function isPlainObject(value: unknown): value is Record<string, unknown> {
136	  return typeof value === 'object' && value !== null && !Array.isArray(value);
137	}
138	
139	function validatePath(p: string, where: string): void {
140	  if (p.length === 0 || p[0] !== '/') {
141	    throw new ConfigError(`${where}.path 必须是以 "/" 开头的绝对路径，收到 "${p}"`);
142	  }
143	  if (p.length > 4096) {
144	    throw new ConfigError(`${where}.path 过长（最多 4096 字符）`);
145	  }
146	  for (const ch of p) {
147	    const code = ch.charCodeAt(0);
148	    if (ch === '?' || ch === '#' || ch === '{' || ch === '}') {
149	      throw new ConfigError(
150	        `${where}.path "${p}" 含有非法字符 "${ch}"：查询串不参与匹配，且不支持路径模板`,
151	      );
152	    }
153	    if (code <= 0x1f || code === 0x7f || code === 0x20) {
154	      throw new ConfigError(`${where}.path "${p}" 不得包含空白或控制字符`);
155	    }
156	  }
157	}
158	
159	function validateResponse(raw: unknown, where: string): ResponseSpec {
160	  if (!isPlainObject(raw)) {
161	    throw new ConfigError(`${where} 必须是对象`);
162	  }
163	  for (const key of Object.keys(raw)) {
164	    if (key !== 'status' && key !== 'headers' && key !== 'body' && key !== 'delay') {
165	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
166	    }
167	  }
168	
169	  const { status, headers, body, delay } = raw;
170	
171	  if (!Number.isInteger(status) || status < 200 || status > 599) {
172	    throw new ConfigError(`${where}.status 必须是 200 至 599 之间的整数，收到 ${JSON.stringify(status)}`);
173	  }
174	
175	  if (!isPlainObject(headers)) {
176	    throw new ConfigError(`${where}.headers 必须是字符串键值对象`);
177	  }
178	  // 无原型对象：名为 "__proto__" 的头也按自有字段保留，不被原型 setter 吞掉
179	  const cleanHeaders: { [name: string]: string } = Object.create(null);
180	  const seenNames = new Set<string>();
181	  for (const [name, value] of Object.entries(headers)) {
182	    const whereHeader = `${where}.headers["${name}"]`;
183	    if (!HEADER_NAME_RE.test(name)) {
184	      throw new ConfigError(`${whereHeader} 不是合法的 HTTP 响应头名称`);
185	    }
186	    const lower = name.toLowerCase();
187	    if (BLOCKED_HEADERS.has(lower)) {
188	      throw new ConfigError(`${whereHeader} 属于服务器管理的传输头，不允许在配置中设置`);
189	    }
190	    if (seenNames.has(lower)) {
191	      throw new ConfigError(`${whereHeader} 与同序列内另一个响应头仅大小写不同，视为重复`);
192	    }
193	    if (typeof value !== 'string') {
194	      throw new ConfigError(`${whereHeader} 的值必须是字符串`);
195	    }
196	    for (let i = 0; i < value.length; i += 1) {
197	      const code = value.charCodeAt(i);
198	      // 允许水平制表符(0x09)；拒绝换行及其余控制字符；
199	      // Node 的 HTTP 头值只支持 Latin-1（0x80-0xFF），更高码位发送时会抛错
200	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
201	        throw new ConfigError(
202	          `${whereHeader} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
203	        );
204	      }
205	    }
206	    seenNames.add(lower);
207	    cleanHeaders[name] = value;
208	  }
209	
210	  if (typeof body !== 'string') {
211	    throw new ConfigError(`${where}.body 必须是文本字符串`);
212	  }
213	  if ((status === 204 || status === 304) && body !== '') {
214	    throw new ConfigError(`${where}.body 状态码为 ${status} 时正文必须为空字符串`);
215	  }
216	
217	  if (!Number.isInteger(delay) || delay < 0 || delay > 60000) {
218	    throw new ConfigError(`${where}.delay 必须是 0 至 60000 之间的整数毫秒数，收到 ${JSON.stringify(delay)}`);
219	  }
220	
221	  return { status, headers: cleanHeaders, body, delay };
222	}
223	
224	const SCALAR_KINDS: ReadonlySet<string> = new Set([
225	  'string',
226	  'number',
227	  'integer',
228	  'boolean',
229	  'null',
230	]);
231	
232	function validateBodyRule(raw: unknown, where: string): BodyRule {
233	  if (!isPlainObject(raw)) {
234	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
235	  }
236	
237	  const type = raw.type;
238	  const allowed = new Set(['type']);
239	  if (type === 'object') {
240	    allowed.add('fields');
241	    allowed.add('additionalProperties');
242	  } else if (type === 'array') {
243	    allowed.add('items');
244	  } else if (!SCALAR_KINDS.has(type as string)) {
245	    throw new ConfigError(
246	      `${where}.type 必须是 "object" | "array" | "string" | "number" | "integer" | "boolean" | "null"，收到 ${JSON.stringify(type)}`,
247	    );
248	  }
249	  for (const key of Object.keys(raw)) {
250	    if (!allowed.has(key)) {
251	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
252	    }
253	  }
254	
255	  if (type === 'object') {
256	    const fieldsRaw = raw.fields;
257	    const fields = new Map<string, FieldRule>();
258	    if (fieldsRaw !== undefined) {
259	      if (!isPlainObject(fieldsRaw)) {
260	        throw new ConfigError(`${where}.fields 必须是对象（字段名 → 字段规则）`);
261	      }
262	      for (const [name, fieldRaw] of Object.entries(fieldsRaw)) {
263	        fields.set(name, validateFieldRule(fieldRaw, `${where}.fields[${JSON.stringify(name)}]`));
264	      }
265	    }
266	    const additional = raw.additionalProperties;
267	    if (additional !== undefined && typeof additional !== 'boolean') {
268	      throw new ConfigError(`${where}.additionalProperties 必须是布尔值`);
269	    }
270	    // 未声明字段默认拒绝
271	    return { kind: 'object', fields, additionalProperties: additional === true };
272	  }
273	
274	  if (type === 'array') {
275	    if (raw.items === undefined) {
276	      throw new ConfigError(`${where}.items 数组规则必须声明元素规则`);
277	    }
278	    return { kind: 'array', items: validateBodyRule(raw.items, `${where}.items`) };
279	  }
280	
281	  return { kind: type as ScalarKind };
282	}
283	
284	// 字段规则 = 任意规则 + 可选 "required"（仅允许出现在 object 的 fields 条目中）
285	function validateFieldRule(raw: unknown, where: string): FieldRule {
286	  if (!isPlainObject(raw)) {
287	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
288	  }
289	  let required = false;
290	  // 无原型对象：未知规则键 "__proto__" 必须作为自有字段保留下来，
291	  // 交由 validateBodyRule 拒绝；普通对象字面量会在复制时被原型 setter 吞掉
292	  const rest: Record<string, unknown> = Object.create(null);
293	  for (const [key, value] of Object.entries(raw)) {
294	    if (key === 'required') {
295	      if (typeof value !== 'boolean') {
296	        throw new ConfigError(`${where}.required 必须是布尔值`);
297	      }
298	      required = value;
299	    } else {
300	      rest[key] = value;
301	    }
302	  }
303	  return { rule: validateBodyRule(rest, where), required };
304	}
305	
306	function validateEndpoint(
307	  raw: unknown,
308	  index: number,
309	  seen: Set<string>,
310	): EndpointSpec {
311	  const where = `endpoints[${index}]`;
312	  if (!isPlainObject(raw)) {
313	    throw new ConfigError(`${where} 必须是对象`);
314	  }
315	  for (const key of Object.keys(raw)) {
316	    if (key !== 'method' && key !== 'path' && key !== 'responses' && key !== 'requestBody') {
317	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
318	    }
319	  }
320	
321	  const { method, path: routePath, responses, requestBody } = raw;
322	
323	  if (method !== 'GET' && method !== 'POST') {
324	    throw new ConfigError(`${where}.method 必须是 "GET" 或 "POST"，收到 ${JSON.stringify(method)}`);
325	  }
326	
327	  if (typeof routePath !== 'string') {
328	    throw new ConfigError(`${where}.path 必须是字符串`);
329	  }
330	  validatePath(routePath, where);
331	  if (routePath === '/__contractlab' || routePath.startsWith(ADMIN_PREFIX)) {
332	    throw new ConfigError(
333	      `${where}.path "${routePath}" 与管理入口冲突：前缀 "${ADMIN_PREFIX}" 为管理接口保留`,
334	    );
335	  }
336	
337	  const key = `${method} ${routePath}`;
338	  if (seen.has(key)) {
339	    throw new ConfigError(`${where} 与其他接口重复（方法 + 路径必须唯一）：${key}`);
340	  }
341	  seen.add(key);
342	
343	  if (!Array.isArray(responses) || responses.length === 0) {
344	    throw new ConfigError(`${where}.responses 必须是非空数组`);
345	  }
346	  const cleanResponses = responses.map((item, j) =>
347	    validateResponse(item, `${where}.responses[${j}]`),
348	  );
349	
350	  let bodyRule: BodyRule | undefined;
351	  if (requestBody !== undefined) {
352	    if (method !== 'POST') {
353	      throw new ConfigError(`${where}.requestBody 仅允许在 POST 接口上声明（GET 接口不允许携带此规则）`);
354	    }
355	    bodyRule = validateBodyRule(requestBody, `${where}.requestBody`);
356	  }
357	
358	  return { method, path: routePath, responses: cleanResponses, bodyRule };
359	}
360	
361	function validateConfig(raw: unknown): EndpointSpec[] {
362	  if (!isPlainObject(raw)) {
363	    throw new ConfigError('配置顶层必须是 JSON 对象');
364	  }
365	  for (const key of Object.keys(raw)) {
366	    if (key !== 'endpoints') {
367	      throw new ConfigError(`未知顶层字段 "${key}"，仅允许 "endpoints"`);
368	    }
369	  }
370	  const list = raw.endpoints;
371	  if (!Array.isArray(list) || list.length === 0) {
372	    throw new ConfigError('endpoints 必须是至少包含一个接口的数组');
373	  }
374	  const seen = new Set<string>();
375	  return list.map((ep, i) => validateEndpoint(ep, i, seen));
376	}
377	
378	// ---------------------------------------------------------------------------
379	// 运行时状态：配置快照 + 每接口独立序列
380	// ---------------------------------------------------------------------------
381	
382	function buildState(version: number, specs: readonly EndpointSpec[]): LiveState {
383	  const endpoints = new Map<string, LiveEndpoint>();
384	  for (const spec of specs) {
385	    endpoints.set(`${spec.method} ${spec.path}`, {
386	      key: `${spec.method} ${spec.path}`,
387	      responses: spec.responses,
388	      bodyRule: spec.bodyRule,
389	      cursor: 0,
390	    });
391	  }
392	  return { version, endpoints };
393	}
394	
395	// 同步预留下一项；同一事件循环内按“完整接收”事件的先后串行调用，天然保序。
396	// 末项之后持续返回末项，不跳项、不复用未到位置的项。
397	// 返回本次消费位置（0 起）与该项；末项复用时位置停在 length-1。
398	function reserveNext(endpoint: LiveEndpoint): { position: number; item: ResponseSpec } {
399	  const last = endpoint.responses.length - 1;
400	  const position = endpoint.cursor < last ? endpoint.cursor : last;
401	  if (endpoint.cursor < last) {
402	    endpoint.cursor += 1;
403	  }
404	  return { position, item: endpoint.responses[position] };
405	}
406	
407	// ---------------------------------------------------------------------------
408	// 进程内请求记录
409	// ---------------------------------------------------------------------------
410	//
411	// 仅记录管理范围之外、完整接收且未超过正文上限的请求（场景响应、400、404）。
412	// 未收完整即断开或超出上限不创建记录、不消费序列。
413	// 编号按“完整接收”顺序在进程内单调递增，与接口消费位置是两回事；
414	// 清空与成功/失败重载都保留编号序列，编号不复用。记录只存在内存中，不写文件。
415	
416	// 写出生命周期（仅指服务器侧写出，不表示客户端已收到）：
417	//   pending     —— 已完整接收、计划响应待发送（延迟期间即可查到）
418	//   sent        —— 服务器已完成响应写出；此后连接正常关闭不再改变状态
419	//   interrupted —— 写出完成前连接断开或写入/发送失败
420	type DeliveryStatus = 'pending' | 'sent' | 'interrupted';
421	
422	// 计划响应：场景响应为 'scene'，400/404 等框架响应为 'framework'
423	interface PlannedResponseSnapshot {
424	  readonly kind: 'scene' | 'framework';
425	  readonly status: number;
426	  // 应用层响应头：配置头/框架头 + 服务器填写的准确版本头，不含传输层自动头
427	  readonly headers: { readonly [name: string]: string };
428	  // 配置/框架给出的响应正文文本（不含 HTTP 层按 Content-Length 等补出的字节）
429	  readonly body: string;
430	}
431	
432	interface RequestRecord {
433	  readonly id: number;
434	  readonly receivedAt: string;
435	  readonly request: {
436	    readonly method: string;
437	    // 含查询串的原始请求目标
438	    readonly target: string;
439	    readonly path: string;
440	    // 原始请求头：按在线顺序成对保留，名称大小写与重复头均不折叠
441	    readonly rawHeaders: readonly string[];
442	    readonly bodyBytes: number;
443	    // 正文原始字节的无损表示：合法 UTF-8 时以文本给出，否则以 base64 给出
444	    readonly body: { readonly encoding: 'utf-8' | 'base64'; readonly content: string };
445	  };
446	  // 完整接收那一刻选用的配置版本；在途请求的结论不随之后的 reload 改变
447	  configVersion: number;
448	  // matched=false：未匹配（404），不消费任何序列
449	  matched: boolean;
450	  endpoint: string | null;
451	  // null 表示未做正文校验（GET/未声明规则）；true=通过，false=拒绝并返回 400
452	  bodyValidationPassed: boolean | null;
453	  // 400 时实际返回的差异报告（与响应正文中的 JSON 同一份数据）
454	  bodyRejection: BodyReport | null;
455	  // 场景请求在序列中的消费位置（0 起）；400/404 没有消费位置，记为 null
456	  sequencePosition: number | null;
457	  sequenceLength: number | null;
458	  plannedResponse: PlannedResponseSnapshot | null;
459	  delivery: DeliveryStatus;
460	}
461	
462	// 已清空记录的投递回调落到空集合上：不取消响应，旧请求之后完成也不得重新出现。
463	class RequestLog {
464	  private records: RequestRecord[] = [];
465	  // 仍可能被投递事件更新的记录 id 集合（清空后旧 id 不在其中）
466	  private readonly live = new Map<number, RequestRecord>();
467	  private nextId = 1;
468	
469	  create(entry: {
470	    method: string;
471	    target: string;
472	    path: string;
473	    rawHeaders: readonly string[];
474	    body: Buffer;
475	    configVersion: number;
476	  }): RequestRecord {
477	    const id = this.nextId;
478	    this.nextId += 1;
479	    const record: RequestRecord = {
480	      id,
481	      receivedAt: new Date().toISOString(),
482	      request: {
483	        method: entry.method,
484	        target: entry.target,
485	        path: entry.path,
486	        rawHeaders: entry.rawHeaders,
487	        bodyBytes: entry.body.byteLength,
488	        body: encodeBodyLosslessly(entry.body),
489	      },
490	      configVersion: entry.configVersion,
491	      matched: false,
492	      endpoint: null,
493	      bodyValidationPassed: null,
494	      bodyRejection: null,
495	      sequencePosition: null,
496	      sequenceLength: null,
497	      plannedResponse: null,
498	      delivery: 'pending',
499	    };
500	    this.records.push(record);
501	    this.live.set(id, record);
502	    return record;
503	  }
504	
505	  // 写出完成；对已清空（不再存活）的记录是 no-op
506	  markDelivered(id: number, status: DeliveryStatus): void {
507	    const record = this.live.get(id);
508	    if (!record) {
509	      return;
510	    }
511	    // 一旦完成写出即为终态：之后的连接正常关闭不得回退为 interrupted
512	    if (record.delivery === 'sent') {
513	      return;
514	    }
515	    record.delivery = status;
516	  }
517	
518	  // 调用时一致快照：拷贝当前存活记录，不推进任何序列
519	  snapshot(): readonly RequestRecord[] {
520	    return [...this.records];
521	  }
522	
523	  // 清空一次移除当时全部记录（含待发送项）；不取消响应、不改配置/版本/序列。
524	  // 清空前已完整接收的请求随后完成或失败都不再出现。
525	  clear(): number {
526	    const removed = this.records.length;
527	    this.records = [];
528	    this.live.clear();
529	    return removed;
530	  }
531	}
