533	// 原始正文字节的无损文本表示：先尝试严格 UTF-8；失败则用 base64 承载任意字节。
534	// 记录的是原始字节而非解析后的 JSON，避免任何信息损失。
535	// ignoreBOM：开头 BOM（EF BB BF）必须保留在文本中（默认行为会将其丢弃），
536	// 否则文本重新编码回不去原始字节，快照就不再无损。
537	function encodeBodyLosslessly(body: Buffer): { encoding: 'utf-8' | 'base64'; content: string } {
538	  try {
539	    const text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(body);
540	    return { encoding: 'utf-8', content: text };
541	  } catch {
542	    return { encoding: 'base64', content: body.toString('base64') };
543	  }
544	}
