546	// ---------------------------------------------------------------------------
547	// 请求正文校验：媒体类型 → UTF-8 JSON 解析 → 结构比对
548	// ---------------------------------------------------------------------------
549	
550	interface StructureProblem {
551	  readonly pointer: string;
552	  readonly expected: string;
553	  readonly actual: string;
554	}
555	
556	interface BodyReport {
557	  readonly error: 'invalid_request_body';
558	  readonly stage: 'parse' | 'structure';
559	  readonly message: string;
560	  readonly problems: readonly StructureProblem[];
561	}
562	
563	function parseFailure(message: string): BodyReport {
564	  return { error: 'invalid_request_body', stage: 'parse', message, problems: [] };
565	}
566	
567	function jsonTypeOf(value: unknown): string {
568	  if (value === null) {
569	    return 'null';
570	  }
571	  if (Array.isArray(value)) {
572	    return 'array';
573	  }
574	  return typeof value;
575	}
576	
577	// RFC 6901 JSON Pointer 段转义：~ -> ~0，/ -> ~1
578	function escapePointerSegment(segment: string): string {
579	  return segment.replace(/~/g, '~0').replace(/\//g, '~1');
580	}
581	
582	// 结构比对：父节点类型不符时只报告该节点，不再深入制造子节点错误；
583	// 字段缺失（hasOwnProperty 为假）与合法的 JSON null 分开判断。
584	function checkRule(
585	  rule: BodyRule,
586	  value: unknown,
587	  pointer: string,
588	  problems: StructureProblem[],
589	): void {
590	  switch (rule.kind) {
591	    case 'string':
592	    case 'boolean':
593	      if (typeof value !== rule.kind) {
594	        problems.push({ pointer, expected: rule.kind, actual: jsonTypeOf(value) });
595	      }
596	      return;
597	    case 'null':
598	      if (value !== null) {
599	        problems.push({ pointer, expected: 'null', actual: jsonTypeOf(value) });
600	      }
601	      return;
602	    case 'number':
603	      if (typeof value !== 'number' || !Number.isFinite(value)) {
604	        problems.push({ pointer, expected: 'number', actual: jsonTypeOf(value) });
605	      }
606	      return;
607	    case 'integer':
608	      if (!Number.isInteger(value)) {
609	        problems.push({ pointer, expected: 'integer', actual: jsonTypeOf(value) });
610	      }
611	      return;
612	    case 'array': {
613	      if (!Array.isArray(value)) {
614	        problems.push({ pointer, expected: 'array', actual: jsonTypeOf(value) });
615	        return;
616	      }
617	      for (let i = 0; i < value.length; i += 1) {
618	        checkRule(rule.items, value[i], `${pointer}/${i}`, problems);
619	      }
620	      return;
621	    }
622	    case 'object': {
623	      if (!isPlainObject(value)) {
624	        problems.push({ pointer, expected: 'object', actual: jsonTypeOf(value) });
625	        return;
626	      }
627	      for (const [name, field] of rule.fields) {
628	        const childPointer = `${pointer}/${escapePointerSegment(name)}`;
629	        if (!Object.prototype.hasOwnProperty.call(value, name)) {
630	          if (field.required) {
631	            problems.push({
632	              pointer: childPointer,
633	              expected: `${field.rule.kind}（必填字段）`,
634	              actual: 'missing',
635	            });
636	          }
637	        } else {
638	          checkRule(field.rule, value[name], childPointer, problems);
639	        }
640	      }
641	      if (!rule.additionalProperties) {
642	        for (const key of Object.keys(value)) {
643	          if (!rule.fields.has(key)) {
644	            problems.push({
645	              pointer: `${pointer}/${escapePointerSegment(key)}`,
646	              expected: '未声明的字段（不允许）',
647	              actual: jsonTypeOf(value[key]),
648	            });
649	          }
650	        }
651	      }
652	      return;
653	    }
654	  }
655	}
656	
657	// 返回 null 表示校验通过；否则为可直接序列化的 400 差异报告。
658	// contentType 为在线顺序第一项 Content-Type 头值（在线：Node 对重复
659	// content-type 只保留首项；离线 verify：取 rawHeaders 中首个同名头）。
660	// 正文解码与 JSON 解析不重写原文：BOM 与空白按 UTF-8 解码的默认规则处理，
661	// 在线与离线对同一组字节给出同一结论。
662	function validateBodyWithContentType(
663	  contentType: string | undefined,
664	  body: Buffer,
665	  rule: BodyRule,
666	): BodyReport | null {
667	  const mediaType =
668	    typeof contentType === 'string' ? contentType.split(';', 1)[0].trim().toLowerCase() : '';
669	  if (mediaType !== 'application/json') {
670	    return parseFailure(
671	      typeof contentType === 'string'
672	        ? `媒体类型不符：期望 application/json（可带参数、忽略大小写），收到 "${contentType}"`
673	        : '缺少 Content-Type 头：期望 application/json（可带参数、忽略大小写）',
674	    );
675	  }
676	
677	  if (body.length === 0) {
678	    return parseFailure('请求正文为空，无法解析为 JSON');
679	  }
680	
681	  let text: string;
682	  try {
683	    text = new TextDecoder('utf-8', { fatal: true }).decode(body);
684	  } catch {
685	    return parseFailure('请求正文不是合法的 UTF-8 编码');
686	  }
687	
688	  let parsed: unknown;
689	  try {
690	    parsed = JSON.parse(text);
691	  } catch (e) {
692	    return parseFailure(`请求正文不是合法 JSON：${describeError(e)}`);
693	  }
694	
695	  const problems: StructureProblem[] = [];
696	  checkRule(rule, parsed, '', problems);
697	  if (problems.length > 0) {
698	    return {
699	      error: 'invalid_request_body',
700	      stage: 'structure',
701	      message: `请求正文与接口约定存在 ${problems.length} 处差异`,
702	      problems,
703	    };
704	  }
705	  return null;
706	}
