708	// ---------------------------------------------------------------------------
709	// 文件读取与（重新）加载：读、解析、校验全部通过后才一次性替换
710	// ---------------------------------------------------------------------------
711	
712	function describeError(e: unknown): string {
713	  return e instanceof Error ? e.message : String(e);
714	}
715	
716	// 读取 -> 解析 -> 严格校验；任何一步失败都抛出含文件路径与可定位原因的错误
717	async function loadSpecsFromFile(configPath: string): Promise<EndpointSpec[]> {
718	  let text: string;
719	  try {
720	    text = await readFile(configPath, 'utf8');
721	  } catch (e) {
722	    throw new Error(`读取配置文件 ${configPath} 失败：${describeError(e)}`);
723	  }
724	
725	  let raw: unknown;
726	  try {
727	    raw = JSON.parse(text);
728	  } catch (e) {
729	    throw new Error(`配置文件 ${configPath} 不是合法 JSON：${describeError(e)}`);
730	  }
731	
732	  try {
733	    return validateConfig(raw);
734	  } catch (e) {
735	    throw new Error(`配置文件 ${configPath} 校验失败：${describeError(e)}`);
736	  }
737	}
738	
739	async function loadStateFromFile(configPath: string, version: number): Promise<LiveState> {
740	  return buildState(version, await loadSpecsFromFile(configPath));
741	}
