743	// ---------------------------------------------------------------------------
744	// 离线兼容报告（compare 子命令）
745	// ---------------------------------------------------------------------------
746	//
747	// 兼容方向固定为 旧 -> 新：旧配置能按“方法 + 字面路径”匹配且通过正文检查的
748	// 每一种请求，在新配置中仍须匹配并通过。只比较接口存在性与请求接受条件；
749	// 响应状态/头/正文/延迟与序列差异不影响结论。
750	//
751	// 双方都配置 requestBody 时，比较的是“规则所接受 JSON 值的集合包含关系”
752	// L(旧规则) ⊆ L(新规则)，而不是文本比较或抽样请求；每个不兼容点都附一份
753	// 具体反例（旧规则接受、新规则拒绝的完整 JSON 值）。
754	
755	interface ReportReason {
756	  // 正文差异：RFC 6901 指针（根为 ""）；接口级原因（如接口删除）无此字段
757	  readonly pointer?: string;
758	  readonly message: string;
759	}
760	
761	interface ReportExample {
762	  readonly method: HttpMethod;
763	  readonly path: string;
764	  readonly headers: { readonly [name: string]: string };
765	  readonly body: string;
766	}
767	
768	interface EndpointReport {
769	  readonly method: HttpMethod;
770	  readonly path: string;
771	  readonly compatible: boolean;
772	  readonly reasons: readonly ReportReason[];
773	  readonly example?: ReportExample;
774	}
775	
776	interface CompareReport {
777	  readonly compatible: boolean;
778	  readonly oldFile: string;
779	  readonly newFile: string;
780	  readonly endpoints: readonly EndpointReport[];
781	}
782	
783	interface BodyViolation {
784	  readonly pointer: string;
785	  readonly message: string;
786	  // 完整请求正文反例：被旧规则接受、被新规则拒绝
787	  readonly value: unknown;
788	}
789	
790	// 生成被规则接受的最小 JSON 值：object 只含必填字段，array 取空数组。
791	// 字段名可能是 "" 或 "__proto__"，一律用无原型对象按自有字段构造。
792	function sampleValue(rule: BodyRule): unknown {
793	  switch (rule.kind) {
794	    case 'string':
795	      return 'contractlab';
796	    case 'number':
797	    case 'integer':
798	      return 0;
799	    case 'boolean':
800	      return false;
801	    case 'null':
802	      return null;
803	    case 'array':
804	      return [];
805	    case 'object': {
806	      const obj: Record<string, unknown> = Object.create(null);
807	      for (const [name, field] of rule.fields) {
808	        if (field.required) {
809	          obj[name] = sampleValue(field.rule);
810	        }
811	      }
812	      return obj;
813	    }
814	  }
815	}
816	
817	// 在 object 规则的最小样本上补一个字段（字段值本身须被该字段规则接受）
818	function sampleObjectWith(
819	  rule: Extract<BodyRule, { kind: 'object' }>,
820	  name: string,
821	  value: unknown,
822	): Record<string, unknown> {
823	  const obj = sampleValue(rule) as Record<string, unknown>;
824	  obj[name] = value;
825	  return obj;
826	}
827	
828	// 生成被规则拒绝的 JSON 值（顶层类型即不符；任何规则都存在这样的值）
829	function violateValue(rule: BodyRule): unknown {
830	  switch (rule.kind) {
831	    case 'number':
832	      return 'contractlab'; // 非数字
833	    case 'integer':
834	      return 0.5; // 非整数
835	    default:
836	      return 0; // 非 string / boolean / null / object / array
837	  }
838	}
839	
840	function kindLabel(rule: BodyRule): string {
841	  if (rule.kind === 'object') {
842	    return rule.additionalProperties ? 'object（允许未声明字段）' : 'object（拒绝未声明字段）';
843	  }
844	  return rule.kind;
845	}
846	
847	// 选一个两个规则都未声明的字段名，用于构造“额外字段”反例
848	function freshFieldName(
849	  oldFields: ReadonlyMap<string, FieldRule>,
850	  newFields: ReadonlyMap<string, FieldRule>,
851	): string {
852	  for (let i = 0; ; i += 1) {
853	    const name = i === 0 ? 'extra' : `extra_${i}`;
854	    if (!oldFields.has(name) && !newFields.has(name)) {
855	      return name;
856	    }
857	  }
858	}
859	
860	// 递归判定 L(oldRule) ⊆ L(newRule)；把发现的每个反例（连同完整正文样本）推入 out。
861	// 不变式：value 必被 oldRule 接受、被 newRule 拒绝；pointer 用 RFC 6901 定位差异。
862	function collectViolations(
863	  oldRule: BodyRule,
864	  newRule: BodyRule,
865	  pointer: string,
866	  out: BodyViolation[],
867	): void {
868	  if (newRule.kind !== 'object' && newRule.kind !== 'array') {
869	    // 标量：仅同名兼容，外加 integer 放宽为 number；其余组合两集合相交为空或有差异
870	    const compatible =
871	      oldRule.kind === newRule.kind || (oldRule.kind === 'integer' && newRule.kind === 'number');
872	    if (!compatible) {
873	      // number -> integer 时样本必须是非整数，否则 0 会被新规则接受
874	      const value =
875	        oldRule.kind === 'number' && newRule.kind === 'integer' ? 0.5 : sampleValue(oldRule);
876	      out.push({
877	        pointer,
878	        value,
879	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 ${newRule.kind}`,
880	      });
881	    }
882	    return;
883	  }
884	
885	  if (newRule.kind === 'array') {
886	    if (oldRule.kind !== 'array') {
887	      out.push({
888	        pointer,
889	        value: sampleValue(oldRule),
890	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 array`,
891	      });
892	      return;
893	    }
894	    // 元素规则收紧：用非空数组 [反例] 体现（空数组双方都会接受）
895	    const sub: BodyViolation[] = [];
896	    collectViolations(oldRule.items, newRule.items, `${pointer}/0`, sub);
897	    for (const s of sub) {
898	      out.push({ pointer: s.pointer, message: s.message, value: [s.value] });
899	    }
900	    return;
901	  }
902	
903	  // newRule.kind === 'object'
904	  if (oldRule.kind !== 'object') {
905	    out.push({
906	      pointer,
907	      value: sampleValue(oldRule),
908	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 object`,
909	    });
910	    return;
911	  }
912	
913	  // (a) 新规则的必填字段必须被旧规则保证存在（旧规则未声明或仅可选即存在反例）
914	  for (const [name, newField] of newRule.fields) {
915	    if (!newField.required) {
916	      continue;
917	    }
918	    const oldField = oldRule.fields.get(name);
919	    if (!oldField || !oldField.required) {
920	      out.push({
921	        pointer: `${pointer}/${escapePointerSegment(name)}`,
922	        // 旧规则的最小样本不含可缺省/未声明字段，恰为反例
923	        value: sampleValue(oldRule),
924	        message: `新规则要求必填字段 ${JSON.stringify(name)}，旧规则允许缺省该字段`,
925	      });
926	    }
927	  }
928	
929	  // (b) 旧规则声明的字段，在新规则下仍须被接受
930	  for (const [name, oldField] of oldRule.fields) {
931	    const childPointer = `${pointer}/${escapePointerSegment(name)}`;
932	    const newField = newRule.fields.get(name);
933	    if (!newField) {
934	      if (!newRule.additionalProperties) {
935	        out.push({
936	          pointer: childPointer,
937	          value: sampleObjectWith(oldRule, name, sampleValue(oldField.rule)),
938	          message: `新规则拒绝旧规则允许的字段 ${JSON.stringify(name)}（新规则未声明且 additionalProperties 为 false）`,
939	        });
940	      }
941	      continue;
942	    }
943	    const sub: BodyViolation[] = [];
944	    collectViolations(oldField.rule, newField.rule, childPointer, sub);
945	    for (const s of sub) {
946	      out.push({
947	        pointer: s.pointer,
948	        message: s.message,
949	        value: sampleObjectWith(oldRule, name, s.value),
950	      });
951	    }
952	  }
953	
954	  // (c) 旧规则允许未声明的额外字段时，新规则必须同样放行这些字段
955	  if (oldRule.additionalProperties) {
956	    if (!newRule.additionalProperties) {
957	      const name = freshFieldName(oldRule.fields, newRule.fields);
958	      out.push({
959	        pointer: `${pointer}/${escapePointerSegment(name)}`,
960	        value: sampleObjectWith(oldRule, name, 0),
961	        message: '旧规则允许未声明的额外字段，新规则拒绝（additionalProperties 为 false）',
962	      });
963	    } else {
964	      // 新规则虽放行额外字段，但其新声明的字段会约束旧版原本自由的取值
965	      for (const [name, newField] of newRule.fields) {
966	        if (oldRule.fields.has(name)) {
967	          continue;
968	        }
969	        out.push({
970	          pointer: `${pointer}/${escapePointerSegment(name)}`,
971	          value: sampleObjectWith(oldRule, name, violateValue(newField.rule)),
972	          message: `旧规则对额外字段 ${JSON.stringify(name)} 不限制取值，新规则要求其为 ${kindLabel(newField.rule)}`,
973	        });
974	      }
975	    }
976	  }
977	}
978	
979	// 旧接口被旧配置接受的一个请求样本（用于“接口已删除”反例）
980	function acceptedRequestExample(endpoint: EndpointSpec): ReportExample {
981	  if (endpoint.bodyRule) {
982	    return {
983	      method: endpoint.method,
984	      path: endpoint.path,
985	      headers: { 'Content-Type': 'application/json' },
986	      body: JSON.stringify(sampleValue(endpoint.bodyRule)),
987	    };
988	  }
989	  return { method: endpoint.method, path: endpoint.path, headers: {}, body: '' };
990	}
991	
992	function compareEndpoint(oldEp: EndpointSpec, newEp: EndpointSpec | undefined): EndpointReport {
993	  const base = { method: oldEp.method, path: oldEp.path };
994	
995	  if (!newEp) {
996	    return {
997	      ...base,
998	      compatible: false,
999	      reasons: [
1000	        { message: '新配置中不存在该接口：按 方法 + 字面路径 匹配不到，旧客户端的调用将得到 404' },
1001	      ],
1002	      example: acceptedRequestExample(oldEp),
1003	    };
1004	  }
1005	
1006	  if (!oldEp.bodyRule && !newEp.bodyRule) {
1007	    return { ...base, compatible: true, reasons: [] };
1008	  }
1009	
1010	  if (!oldEp.bodyRule && newEp.bodyRule) {
1011	    // 旧版允许任意媒体类型与正文；新版启用校验即存在被拒绝的旧请求
1012	    return {
1013	      ...base,
1014	      compatible: false,
1015	      reasons: [
1016	        {
1017	          pointer: '',
1018	          message: '旧接口不校验请求正文（任意媒体类型与正文均可），新接口启用了 requestBody 正文校验',
1019	        },
1020	      ],
1021	      example: {
1022	        ...base,
1023	        headers: { 'Content-Type': 'application/json' },
1024	        body: JSON.stringify(violateValue(newEp.bodyRule)),
1025	      },
1026	    };
1027	  }
1028	
1029	  if (oldEp.bodyRule && !newEp.bodyRule) {
1030	    return { ...base, compatible: true, reasons: [] }; // 移除规则更宽松
1031	  }
1032	
1033	  const violations: BodyViolation[] = [];
1034	  collectViolations(oldEp.bodyRule as BodyRule, newEp.bodyRule as BodyRule, '', violations);
1035	  if (violations.length === 0) {
1036	    return { ...base, compatible: true, reasons: [] };
1037	  }
1038	  return {
1039	    ...base,
1040	    compatible: false,
1041	    reasons: violations.map((v) => ({ pointer: v.pointer, message: v.message })),
1042	    example: {
1043	      ...base,
1044	      headers: { 'Content-Type': 'application/json' },
1045	      body: JSON.stringify(violations[0].value),
1046	    },
1047	  };
1048	}
