1050	function compareConfigs(
1051	  oldSpecs: readonly EndpointSpec[],
1052	  newSpecs: readonly EndpointSpec[],
1053	  oldFile: string,
1054	  newFile: string,
1055	): CompareReport {
1056	  const newByKey = new Map<string, EndpointSpec>();
1057	  for (const spec of newSpecs) {
1058	    newByKey.set(`${spec.method} ${spec.path}`, spec);
1059	  }
1060	  const endpoints = oldSpecs.map((spec) =>
1061	    compareEndpoint(spec, newByKey.get(`${spec.method} ${spec.path}`)),
1062	  );
1063	  return {
1064	    compatible: endpoints.every((ep) => ep.compatible),
1065	    oldFile,
1066	    newFile,
1067	    endpoints,
1068	  };
1069	}
