1071	async function runCompare(oldArg: string, newArg: string): Promise<never> {
1072	  const oldFile = path.resolve(oldArg);
1073	  const newFile = path.resolve(newArg);
1074	
1075	  const attempt = async (
1076	    file: string,
1077	  ): Promise<{ specs?: EndpointSpec[]; error?: string }> => {
1078	    try {
1079	      return { specs: await loadSpecsFromFile(file) };
1080	    } catch (e) {
1081	      return { error: describeError(e) };
1082	    }
1083	  };
1084	
1085	  // 两份文件都完整经历 读取 -> 解析 -> 严格校验；任一失败则不输出任何报告
1086	  const [oldResult, newResult] = await Promise.all([attempt(oldFile), attempt(newFile)]);
1087	  let failed = false;
1088	  if (oldResult.error !== undefined) {
1089	    process.stderr.write(`${APP_NAME}: compare 旧文件：${oldResult.error}\n`);
1090	    failed = true;
1091	  }
1092	  if (newResult.error !== undefined) {
1093	    process.stderr.write(`${APP_NAME}: compare 新文件：${newResult.error}\n`);
1094	    failed = true;
1095	  }
1096	  if (failed) {
1097	    process.exit(2);
1098	  }
1099	
1100	  const report = compareConfigs(
1101	    oldResult.specs as EndpointSpec[],
1102	    newResult.specs as EndpointSpec[],
1103	    oldFile,
1104	    newFile,
1105	  );
1106	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
1107	  process.exit(report.compatible ? 0 : 1);
1108	}
