1167	// 转换过程中的规范化规则：与 BodyRule 同构，但 object 的必填名集合单独保存，
1168	// 便于 allOf 交集计算；输出时再展开为场景规则 JSON。
1169	type NormRule =
1170	  | {
1171	      readonly kind: 'object';
1172	      readonly props: ReadonlyMap<string, NormRule>;
1173	      readonly required: ReadonlySet<string>;
1174	      readonly addl: boolean;
1175	    }
1176	  | { readonly kind: 'array'; readonly items: NormRule }
1177	  | { readonly kind: 'string' | 'number' | 'integer' | 'boolean' };
