1198	  'title',
1199	  'description',
1200	  'example',
1201	  'nullable',
1202	]);
1203	
1204	const OPENAPI_SCALAR_TYPES: ReadonlySet<string> = new Set([
1205	  'string',
1206	  'number',
1207	  'integer',
1208	  'boolean',
1209	]);
