1215	// JSON Pointer 段反转义：~1 -> /，~0 -> ~；其余 “~” 用法非法
1216	function unescapeRefSegment(
1217	  segment: string,
1218	  ref: string,
1219	  ctx: ImportCtx,
1220	  where: string,
1221	): string {
1222	  let out = '';
1223	  for (let i = 0; i < segment.length; i += 1) {
1224	    const ch = segment[i];
1225	    if (ch === '~') {
1226	      const next = segment[i + 1];
1227	      if (next === '0') {
1228	        out += '~';
1229	        i += 1;
1230	      } else if (next === '1') {
1231	        out += '/';
1232	        i += 1;
1233	      } else {
1234	        importFail(ctx, where, `$ref "${ref}" 含非法的 "~" 转义（仅支持 ~0 与 ~1）`);
1235	      }
1236	    } else {
1237	      out += ch;
1238	    }
1239	  }
1240	  return out;
1241	}
