1243	// 解析一层 $ref：node 是“只含 $ref 的引用节点”时返回目标与新的位置/引用链，
1244	// 否则返回 null。外部引用、非法指针、目标缺失、循环引用都在此拒绝。
1245	function dereference(
1246	  node: Record<string, unknown>,
1247	  ctx: ImportCtx,
1248	  where: string,
1249	  refChain: readonly string[],
1250	): { target: unknown; where: string; refChain: readonly string[] } | null {
1251	  if (!hasOwnKey(node, '$ref')) {
1252	    return null;
1253	  }
1254	  if (Object.keys(node).length !== 1) {
1255	    importFail(ctx, where, '含 $ref 的引用节点不得包含其他字段（只允许 "$ref"）');
1256	  }
1257	  const ref = node.$ref;
1258	  if (typeof ref !== 'string' || !ref.startsWith('#')) {
1259	    importFail(
1260	      ctx,
1261	      where,
1262	      `仅支持本文件内 $ref（以 "#" 开头的 JSON Pointer），收到 ${JSON.stringify(ref)}`,
1263	    );
1264	  }
1265	  if (refChain.includes(ref as string)) {
1266	    importFail(ctx, where, `循环 $ref 引用：${[...refChain, ref].join(' -> ')}`);
1267	  }
1268	  const fragment = (ref as string).slice(1);
1269	  let target: unknown = ctx.doc;
1270	  if (fragment !== '') {
1271	    if (!fragment.startsWith('/')) {
1272	      importFail(ctx, where, `$ref "${ref as string}" 不是合法的 JSON Pointer 片段`);
1273	    }
1274	    const segments = fragment
1275	      .slice(1)
1276	      .split('/')
1277	      .map((seg) => unescapeRefSegment(seg, ref as string, ctx, where));
1278	    let traversed = '#';
1279	    for (const segment of segments) {
1280	      traversed = `${traversed}/${escapePointerSegment(segment)}`;
1281	      if (Array.isArray(target)) {
1282	        if (!/^(0|[1-9]\d*)$/.test(segment) || Number(segment) >= target.length) {
1283	          importFail(ctx, where, `$ref "${ref as string}" 的目标不存在：${traversed} 超出数组范围`);
1284	        }
1285	        target = target[Number(segment)];
1286	      } else if (isPlainObject(target)) {
1287	        if (!hasOwnKey(target, segment)) {
1288	          importFail(ctx, where, `$ref "${ref as string}" 的目标不存在：${traversed} 缺失`);
1289	        }
1290	        target = target[segment];
1291	      } else {
1292	        importFail(ctx, where, `$ref "${ref as string}" 无法继续解析：${traversed} 不是对象或数组`);
1293	      }
1294	    }
1295	  }
1296	  return { target, where: `${where} -> ${ref as string}`, refChain: [...refChain, ref as string] };
1297	}
