1299	// 解析一层或多层 $ref 并做节点级基础校验（必须是对象、nullable 仅可 false），
1300	// 返回落定的 schema 节点与其（含引用链的）位置。
1301	function resolveSchemaNode(
1302	  rawNode: unknown,
1303	  ctx: ImportCtx,
1304	  where: string,
1305	  refChain: readonly string[],
1306	): { n: Record<string, unknown>; nodeWhere: string; chain: readonly string[] } {
1307	  let node = rawNode;
1308	  let nodeWhere = where;
1309	  let chain = refChain;
1310	  // 引用节点可以层层指向另一个引用节点
1311	  for (;;) {
1312	    if (!isPlainObject(node)) {
1313	      importFail(ctx, nodeWhere, 'schema 必须是对象');
1314	    }
1315	    const ref = dereference(node, ctx, nodeWhere, chain);
1316	    if (!ref) {
1317	      break;
1318	    }
1319	    node = ref.target;
1320	    nodeWhere = ref.where;
1321	    chain = ref.refChain;
1322	  }
1323	  const n = node as Record<string, unknown>;
1324	  // nullable 仅允许 false（等同不声明，忽略）；true 属于非法值
1325	  if (hasOwnKey(n, 'nullable') && n.nullable !== false) {
1326	    importFail(ctx, `${nodeWhere}.nullable`, `仅支持 false（或不声明），收到 ${JSON.stringify(n.nullable)}`);
