1331	// 组合节点键校验（仅 allOf 与注释）并取出非空 allOf 数组
1332	function comboList(n: Record<string, unknown>, ctx: ImportCtx, nodeWhere: string): unknown[] {
1333	  for (const key of Object.keys(n)) {
1334	    if (key !== 'allOf' && !OPENAPI_ANNOTATION_KEYS.has(key)) {
1335	      importFail(
1336	        ctx,
1337	        nodeWhere,
1338	        `组合节点仅允许 allOf 及注释（title/description/example/nullable），含未支持的关键字 "${key}"`,
1339	      );
1340	    }
1341	  }
1342	  const list = n.allOf;
1343	  if (!Array.isArray(list) || list.length === 0) {
1344	    importFail(ctx, `${nodeWhere}.allOf`, '必须是非空数组');
1345	  }
1346	  return list as unknown[];
1347	}
