1358	function collectObjectLeaves(
1359	  list: readonly unknown[],
1360	  ctx: ImportCtx,
1361	  parentWhere: string,
1362	  chain: readonly string[],
1363	): ObjectLeaf[] {
1364	  const leaves: ObjectLeaf[] = [];
1365	  list.forEach((raw, i) => {
1366	    const branchWhere = `${parentWhere}.allOf[${i}]`;
1367	    const { n, nodeWhere, chain: ch } = resolveSchemaNode(raw, ctx, branchWhere, chain);
1368	    if (hasOwnKey(n, 'allOf')) {
1369	      leaves.push(...collectObjectLeaves(comboList(n, ctx, nodeWhere), ctx, nodeWhere, ch));
1370	      return;
1371	    }
1372	    const rule = buildSimpleNorm(n, ctx, nodeWhere, ch);
1373	    if (rule.kind !== 'object') {
1374	      importFail(ctx, nodeWhere, `仅支持纯对象 allOf 组合，该分支最终类型为 ${rule.kind}`);
1375	    }
1376	    leaves.push({ rule: rule as NormObject, loc: nodeWhere });
1377	  });
1378	  return leaves;
1379	}
