1381	// schema（或引用链尽头的 schema）-> 规范化规则
1382	function schemaToNorm(
1383	  rawNode: unknown,
1384	  ctx: ImportCtx,
1385	  where: string,
1386	  refChain: readonly string[],
1387	): NormRule {
1388	  const { n, nodeWhere, chain } = resolveSchemaNode(rawNode, ctx, where, refChain);
1389	
1390	  if (hasOwnKey(n, 'allOf')) {
1391	    const leaves = collectObjectLeaves(comboList(n, ctx, nodeWhere), ctx, nodeWhere, chain);
1392	    const result = intersectObjects(
1393	      leaves.map((l) => ({ rule: l.rule, loc: l.loc })),
1394	      nodeWhere,
1395	    );
1396	    // 整体空交集 与 非空但无法表达 都拒绝；reason 含冲突字段/元素与失败理由，
1397	    // loc 指向贡献该结论的叶分支（可定位的操作或定义位置）
1398	    if (result.tag === 'empty' || result.tag === 'inexpressible') {
1399	      importFail(ctx, result.loc, result.reason);
1400	    }
1401	    return result.rule;
1402	  }
1403	
1404	  return buildSimpleNorm(n, ctx, nodeWhere, chain);
1405	}
