1407	// 非组合（非 allOf）schema -> 规范化规则
1408	function buildSimpleNorm(
1409	  n: Record<string, unknown>,
1410	  ctx: ImportCtx,
1411	  nodeWhere: string,
1412	  chain: readonly string[],
1413	): NormRule {
1414	  const type = n.type;
1415	  if (
1416	    typeof type !== 'string' ||
1417	    (type !== 'object' && type !== 'array' && !OPENAPI_SCALAR_TYPES.has(type))
1418	  ) {
1419	    importFail(
1420	      ctx,
1421	      `${nodeWhere}.type`,
1422	      `必须是 "object" | "array" | "string" | "number" | "integer" | "boolean"，收到 ${JSON.stringify(n.type)}`,
1423	    );
1424	  }
1425	  const structural: readonly string[] =
1426	    type === 'object'
1427	      ? ['properties', 'required', 'additionalProperties']
1428	      : type === 'array'
1429	        ? ['items']
1430	        : [];
1431	  for (const key of Object.keys(n)) {
1432	    if (key !== 'type' && !OPENAPI_ANNOTATION_KEYS.has(key) && !structural.includes(key)) {
1433	      importFail(ctx, nodeWhere, `含未支持的关键字 "${key}"`);
1434	    }
1435	  }
1436	
1437	  if (type === 'array') {
1438	    if (!hasOwnKey(n, 'items')) {
1439	      importFail(ctx, `${nodeWhere}.items`, '数组 schema 必须声明元素规则 items');
1440	    }
1441	    return { kind: 'array', items: schemaToNorm(n.items, ctx, `${nodeWhere}.items`, chain) };
1442	  }
1443	
1444	  if (type === 'object') {
1445	    const propsRaw = n.properties;
1446	    if (propsRaw !== undefined && !isPlainObject(propsRaw)) {
1447	      importFail(ctx, `${nodeWhere}.properties`, '必须是对象（字段名 -> schema）');
1448	    }
1449	    const reqRaw = n.required;
1450	    const requiredList: string[] = [];
1451	    if (reqRaw !== undefined) {
1452	      if (!Array.isArray(reqRaw)) {
1453	        importFail(ctx, `${nodeWhere}.required`, '必须是字符串数组');
1454	      }
1455	      for (let i = 0; i < (reqRaw as unknown[]).length; i += 1) {
1456	        const item = (reqRaw as unknown[])[i];
1457	        if (typeof item !== 'string') {
1458	          importFail(ctx, `${nodeWhere}.required[${i}]`, `必须是字符串，收到 ${JSON.stringify(item)}`);
1459	        }
1460	        if (requiredList.includes(item as string)) {
1461	          importFail(ctx, `${nodeWhere}.required`, `含重复项 ${JSON.stringify(item)}`);
1462	        }
1463	        requiredList.push(item as string);
1464	      }
1465	    }
1466	    const props = new Map<string, NormRule>();
1467	    if (propsRaw !== undefined) {
1468	      for (const [name, sub] of Object.entries(propsRaw as Record<string, unknown>)) {
1469	        props.set(
1470	          name,
1471	          schemaToNorm(sub, ctx, `${nodeWhere}.properties[${JSON.stringify(name)}]`, chain),
1472	        );
1473	      }
1474	    }
1475	    for (const name of requiredList) {
1476	      if (!props.has(name)) {
