1495	// 标量类型交集：相同类型取自身；number ∩ integer 取 integer；其余组合为空。
1496	// 结果与顺序无关。
1497	function scalarIntersection(
1498	  a: NormRule,
1499	  b: NormRule,
1500	): { kind: 'string' | 'number' | 'integer' | 'boolean' } | null {
