1526	function intersectObjects(flat: readonly RuleBranch[], where: string): Intersection {
1527	  const objs = flat.map((b) => b.rule as NormObject);
1528	  // 结果的 additionalProperties 为各分支的合取（任一分支拒绝则拒绝）
1529	  const addl = objs.every((o) => o.addl);
1530	
1531	  const names: string[] = [];
1532	  const seen = new Set<string>();
1533	  for (const o of objs) {
1534	    for (const name of o.props.keys()) {
1535	      if (!seen.has(name)) {
1536	        seen.add(name);
1537	        names.push(name);
1538	      }
1539	    }
1540	  }
1541	
1542	  const props = new Map<string, NormRule>();
1543	  const required = new Set<string>();
1544	  // 非空但无法表达时的首个原因与位置（可能随后被收窄为空交集）
1545	  let inex: { reason: string; loc: string } | undefined;
1546	
1547	  const noteInexpressible = (reason: string, loc: string): void => {
1548	    if (inex === undefined) {
1549	      inex = { reason, loc };
1550	    }
1551	  };
1552	
1553	  for (const name of names) {
1554	    const isRequired = objs.some((o) => o.required.has(name));
1555	
1556	    // 真正约束该字段取值的声明分支（附精确来源位置）；以及首个禁止它出现的分支
1557	    // （未声明且该分支 additionalProperties 为 false）
1558	    const declarers: RuleBranch[] = [];
1559	    let forbiddener: RuleBranch | undefined;
1560	    for (let i = 0; i < flat.length; i += 1) {
1561	      const o = objs[i];
1562	      const sub = o.props.get(name);
1563	      if (sub !== undefined) {
1564	        declarers.push({ rule: sub, loc: `${flat[i].loc}.properties[${JSON.stringify(name)}]` });
1565	      } else if (!o.addl && forbiddener === undefined) {
1566	        forbiddener = flat[i];
1567	      }
1568	    }
1569	
1570	    if (forbiddener !== undefined) {
1571	      if (isRequired) {
1572	        return {
1573	          tag: 'empty',
1574	          reason:
1575	            `字段 ${JSON.stringify(name)} 在部分分支中为必填，但被另一分支禁止出现` +
1576	            '（未声明且 additionalProperties 为 false），交集为空',
1577	          loc: forbiddener.loc,
1578	        };
1579	      }
1580	      // 可选且被禁止：结果中不声明该字段即“禁止出现”。其余声明分支的取值交集
1581	      // 为何都无关紧要——该字段根本不能出现（声明分支中的非法 schema 仍在
1582	      // schemaToNorm 阶段被拒绝，不会走到这里）。
1583	      continue;
1584	    }
1585	
1586	    // 没有任何分支声明它：各分支仅以“允许额外字段”放行，交集对它无约束
1587	    if (declarers.length === 0) {
1588	      continue;
1589	    }
1590	
1591	    const sub = intersectRules(declarers, `${where}.properties[${JSON.stringify(name)}]`);
1592	
1593	    if (sub.tag === 'empty') {
1594	      if (isRequired) {
1595	        return {
1596	          tag: 'empty',
1597	          reason: `必填字段 ${JSON.stringify(name)} 的各分支规则交集为空：${sub.reason}`,
1598	          loc: sub.loc,
1599	        };
1600	      }
1601	      if (!addl) {
1602	        // 可选字段交集为空、结果又拒绝额外字段：不声明即“禁止出现”，可表达
1603	        continue;
1604	      }
1605	      // 所有分支都允许额外字段时，无法表达“仅该字段禁止出现、其他字段任意”
1606	      noteInexpressible(
1607	        `可选字段 ${JSON.stringify(name)} 的各分支规则交集为空（${sub.reason}），` +
1608	          '且所有分支都允许额外字段，现有规则种类无法表达“仅禁止该字段出现”',
1609	        sub.loc,
