1611	      continue;
1612	    }
1613	
1614	    if (sub.tag === 'inexpressible') {
1615	      // 子级非空但不可表达：本字段可选时外层封闭也许能补救，故带近似规则继续，
1616	      // 先记录原因；必填字段的不可表达在外层封闭也无法补救，最终仍会拒绝。
1617	      noteInexpressible(
1618	        `${isRequired ? '必填' : '可选'}字段 ${JSON.stringify(name)} 的各分支规则交集非空但无法表达：${sub.reason}`,
1619	        sub.loc,
1620	      );
1621	      props.set(name, sub.rule);
1622	      if (isRequired) {
1623	        required.add(name);
1624	      }
1625	      continue;
1626	    }
1627	
1628	    props.set(name, sub.rule);
1629	    if (isRequired) {
1630	      required.add(name);
1631	    }
1632	  }
1633	
1634	  const merged: NormObject = { kind: 'object', props, required, addl };
1635	  if (inex !== undefined) {
1636	    return { tag: 'inexpressible', rule: merged, reason: inex.reason, loc: inex.loc };
1637	  }
1638	  return { tag: 'nonempty', rule: merged };
1639	}
