1641	// 多个规则分支（标量/数组/对象）的交集，三态返回，结论与顺序、分组无关。
1642	function intersectRules(flat: readonly RuleBranch[], where: string): Intersection {
1643	  const first = flat[0].rule;
1644	  const isComposite = (k: NormRule['kind']): boolean => k === 'object' || k === 'array';
1645	
1646	  // 含对象/数组时，全部分支必须是同一种结构类型；对象/数组与标量、对象与数组
1647	  // 相交都为空。纯标量分支（如 number 与 integer）不在此拒绝，交给下方的
1648	  // 标量交集处理（number ∩ integer 取 integer，并非为空）。
1649	  if (isComposite(first.kind)) {
1650	    for (let i = 1; i < flat.length; i += 1) {
1651	      if (flat[i].rule.kind !== first.kind) {
1652	        return {
1653	          tag: 'empty',
1654	          reason: `类型 ${first.kind} 与 ${flat[i].rule.kind} 没有共同接受的值`,
1655	          loc: flat[i].loc,
1656	        };
1657	      }
1658	    }
1659	    if (first.kind === 'object') {
1660	      return intersectObjects(flat, where);
1661	    }
1662	
1663	    // first.kind === 'array'
1664	    // 数组只接受“每个元素都在元素交集内”的序列，空数组总被接受：
1665	    // - 元素交集可表达 -> 非空，items 取交集（空数组也接受）；
1666	    // - 元素交集为空 -> 真实交集仅含空数组，现有规则种类无法表达；
1667	    // - 元素交集非空但不可表达 -> 同样无法在不扩展规则种类的前提下表达。
1668	    const itemBranches: RuleBranch[] = flat.map((b) => ({
1669	      rule: (b.rule as Extract<NormRule, { kind: 'array' }>).items,
1670	      loc: `${b.loc}.items`,
1671	    }));
1672	    const itemRes = intersectRules(itemBranches, `${where}.items`);
1673	    if (itemRes.tag === 'empty') {
1674	      return {
1675	        tag: 'inexpressible',
1676	        rule: { kind: 'array', items: itemBranches[0].rule },
1677	        reason: `数组元素规则交集为空（${itemRes.reason}），交集仅含空数组，现有规则种类无法表达`,
1678	        loc: itemRes.loc,
1679	      };
1680	    }
1681	    if (itemRes.tag === 'inexpressible') {
1682	      return {
1683	        tag: 'inexpressible',
1684	        rule: { kind: 'array', items: itemRes.rule },
1685	        reason: `数组元素规则交集非空但无法表达：${itemRes.reason}`,
1686	        loc: itemRes.loc,
1687	      };
1688	    }
1689	    return { tag: 'nonempty', rule: { kind: 'array', items: itemRes.rule } };
1690	  }
1691	
1692	  // 全为标量（若混入对象/数组，首分支为标量而其后出现复合类型，交集为空）
1693	  for (let i = 1; i < flat.length; i += 1) {
1694	    if (isComposite(flat[i].rule.kind)) {
1695	      return {
1696	        tag: 'empty',
1697	        reason: `类型 ${first.kind} 与 ${flat[i].rule.kind} 没有共同接受的值`,
1698	        loc: flat[i].loc,
1699	      };
1700	    }
1701	  }
1702	
1703	  // 标量：顺序无关地求类型交集（number ∩ integer 取 integer）；遇空即整体为空
1704	  let acc: NormRule = first;
1705	  for (let i = 1; i < flat.length; i += 1) {
1706	    const hit = scalarIntersection(acc, flat[i].rule);
1707	    if (hit === null) {
1708	      return {
1709	        tag: 'empty',
1710	        reason: `类型 ${acc.kind} 与 ${flat[i].rule.kind} 没有共同接受的值`,
1711	        loc: flat[i].loc,
1712	      };
1713	    }
1714	    acc = hit;
1715	  }
1716	  return { tag: 'nonempty', rule: acc };
1717	}
