1719	// 规范化规则 -> 场景规则 JSON（object 显式写出 fields 与 additionalProperties；
1720	// 字段名可能是 ""/"__proto__"/含斜杠波浪号，一律用无原型对象按自有字段构造）
1721	function normToRuleJson(rule: NormRule): Record<string, unknown> {
1722	  switch (rule.kind) {
1723	    case 'object': {
1724	      const fields: Record<string, unknown> = Object.create(null);
1725	      for (const [name, sub] of rule.props) {
1726	        const subJson = normToRuleJson(sub);
1727	        fields[name] = rule.required.has(name) ? { ...subJson, required: true } : subJson;
1728	      }
1729	      return { type: 'object', fields, additionalProperties: rule.addl };
1730	    }
1731	    case 'array':
1732	      return { type: 'array', items: normToRuleJson(rule.items) };
1733	    default:
1734	      return { type: rule.kind };
1735	  }
1736	}
