1738	// 转换一个操作的 requestBody；操作未声明 requestBody 时返回 undefined
1739	// （POST 移除接口旧规则；GET 本就不允许携带规则）。
1740	function importOperationBodyRule(
1741	  operation: Record<string, unknown>,
1742	  method: HttpMethod,
1743	  ctx: ImportCtx,
1744	  opWhere: string,
1745	): unknown {
1746	  if (!hasOwnKey(operation, 'requestBody')) {
1747	    return undefined;
1748	  }
1749	  const rbWhere = `${opWhere}.requestBody`;
1750	  if (method === 'GET') {
1751	    importFail(ctx, rbWhere, 'GET 操作不允许声明请求正文');
1752	  }
1753	  // requestBody 本身也可以是本文件内 $ref（可层层引用）
1754	  let node: unknown = operation.requestBody;
1755	  let nodeWhere = rbWhere;
1756	  let chain: readonly string[] = [];
1757	  for (;;) {
1758	    if (!isPlainObject(node)) {
1759	      importFail(ctx, nodeWhere, '必须是对象');
1760	    }
1761	    const ref = dereference(node, ctx, nodeWhere, chain);
1762	    if (!ref) {
1763	      break;
1764	    }
1765	    node = ref.target;
1766	    nodeWhere = ref.where;
1767	    chain = ref.refChain;
1768	  }
1769	  const rb = node as Record<string, unknown>;
1770	  for (const key of Object.keys(rb)) {
1771	    if (key !== 'required' && key !== 'content' && key !== 'description') {
1772	      importFail(ctx, nodeWhere, `含未支持的字段 "${key}"`);
1773	    }
1774	  }
1775	  if (rb.required !== true) {
1776	    importFail(
1777	      ctx,
1778	      `${nodeWhere}.required`,
1779	      `导入的请求正文约定一律按必填处理，required 必须为 true，收到 ${JSON.stringify(rb.required)}`,
1780	    );
1781	  }
1782	  const content = rb.content;
1783	  if (!isPlainObject(content)) {
1784	    importFail(ctx, `${nodeWhere}.content`, '必须是对象且仅含 "application/json" 一种媒体类型');
1785	  }
1786	  const mediaTypes = Object.keys(content as Record<string, unknown>);
1787	  if (mediaTypes.length !== 1 || mediaTypes[0] !== 'application/json') {
1788	    importFail(
1789	      ctx,
1790	      `${nodeWhere}.content`,
1791	      `仅允许且必须包含 "application/json" 一种媒体类型，收到 ${JSON.stringify(mediaTypes)}`,
1792	    );
1793	  }
1794	  const media = (content as Record<string, unknown>)['application/json'];
1795	  const mediaWhere = `${nodeWhere}.content["application/json"]`;
1796	  if (!isPlainObject(media)) {
1797	    importFail(ctx, mediaWhere, '必须是对象');
1798	  }
1799	  for (const key of Object.keys(media as Record<string, unknown>)) {
1800	    if (key !== 'schema' && key !== 'example' && key !== 'examples') {
1801	      importFail(ctx, mediaWhere, `含未支持的字段 "${key}"`);
1802	    }
1803	  }
1804	  if (!hasOwnKey(media as Record<string, unknown>, 'schema')) {
1805	    importFail(ctx, mediaWhere, '缺少 schema');
1806	  }
1807	  const norm = schemaToNorm(
1808	    (media as Record<string, unknown>).schema,
1809	    ctx,
1810	    `${mediaWhere}.schema`,
1811	    [],
1812	  );
1813	  return normToRuleJson(norm);
1814	}
