1816	// 为场景每个接口选择文档操作并转换；任一失败抛 ImportError，不产生部分输出。
1817	// 未被选中的操作与不可达定义不参与转换。
1818	function importEndpoints(sceneRaw: unknown, ctx: ImportCtx): unknown[] {
1819	  const doc = ctx.doc;
1820	  if (!isPlainObject(doc)) {
1821	    importFail(ctx, '', '顶层必须是 JSON 对象');
1822	  }
1823	  const version = (doc as Record<string, unknown>).openapi;
1824	  if (typeof version !== 'string' || !/^3\.0\.\d+/.test(version)) {
1825	    importFail(ctx, 'openapi', `仅支持 OpenAPI 3.0.x，收到 ${JSON.stringify(version)}`);
1826	  }
1827	  const paths = (doc as Record<string, unknown>).paths;
1828	  if (!isPlainObject(paths)) {
1829	    importFail(ctx, 'paths', '必须是对象（路径 -> 路径项）');
1830	  }
1831	  const endpoints = (sceneRaw as { endpoints: unknown[] }).endpoints;
1832	  return endpoints.map((epRaw, index) => {
1833	    const ep = epRaw as { method: HttpMethod; path: string; responses: unknown };
1834	    const label = `场景接口 endpoints[${index}]（${ep.method} ${ep.path}）`;
1835	    if (!hasOwnKey(paths, ep.path)) {
1836	      importFail(ctx, 'paths', `${label} 缺少对应操作：路径 ${JSON.stringify(ep.path)} 不存在`);
1837	    }
1838	    const pathItem = (paths as Record<string, unknown>)[ep.path];
1839	    const pathWhere = `paths[${JSON.stringify(ep.path)}]`;
1840	    if (!isPlainObject(pathItem)) {
1841	      importFail(ctx, pathWhere, '必须是对象');
1842	    }
1843	    const methodKey = ep.method.toLowerCase();
1844	    if (!hasOwnKey(pathItem, methodKey)) {
1845	      importFail(ctx, pathWhere, `${label} 缺少对应操作：${methodKey} 操作不存在`);
1846	    }
1847	    const operation = (pathItem as Record<string, unknown>)[methodKey];
1848	    const opWhere = `${pathWhere}.${methodKey}`;
1849	    if (!isPlainObject(operation)) {
1850	      importFail(ctx, opWhere, '必须是对象');
1851	    }
1852	    const rule = importOperationBodyRule(operation, ep.method, ctx, opWhere);
1853	    // 仅替换 requestBody：保留接口顺序与 responses 原文
1854	    const out: { method: string; path: string; requestBody?: unknown; responses: unknown } = {
1855	      method: ep.method,
1856	      path: ep.path,
1857	      responses: ep.responses,
1858	    };
1859	    if (rule !== undefined) {
1860	      out.requestBody = rule;
1861	    }
1862	    return out;
1863	  });
1864	}
