2122	  for (const spec of specs) {
2123	    byKey.set(`${spec.method} ${spec.path}`, spec);
2124	  }
2125	  const results = requests.map((req): VerifyResultEntry => {
2126	    const endpoint =
2127	      req.method === 'GET' || req.method === 'POST'
2128	        ? byKey.get(`${req.method} ${req.path}`)
2129	        : undefined;
2130	    if (!endpoint) {
2131	      return { id: req.id, outcome: 'unmatched', endpoint: null };
2132	    }
2133	    const key = `${endpoint.method} ${endpoint.path}`;
2134	    if (endpoint.bodyRule) {
2135	      const rejection = validateBodyWithContentType(req.contentType, req.body, endpoint.bodyRule);
2136	      if (rejection) {
2137	        return { id: req.id, outcome: 'rejected', endpoint: key, rejection };
2138	      }
2139	      return { id: req.id, outcome: 'passed', endpoint: key };
2140	    }
2141	    return { id: req.id, outcome: 'no_body_check', endpoint: key };
2142	  });
2143	  const accepted = results.filter(
2144	    (r) => r.outcome === 'passed' || r.outcome === 'no_body_check',
2145	  ).length;
2146	  return {
2147	    requestsFile,
2148	    configFile,
2149	    total: results.length,
2150	    accepted,
2151	    rejected: results.length - accepted,
2152	    results,
2153	  };
2154	}
