2156	async function runVerify(requestsArg: string, configArg: string): Promise<never> {
2157	  const requestsFile = path.resolve(requestsArg);
2158	  const configFile = path.resolve(configArg);
2159	
2160	  const attemptSnapshot = async (): Promise<{ requests?: SnapshotRequest[]; error?: string }> => {
2161	    try {
2162	      return { requests: await loadSnapshotFromFile(requestsFile) };
2163	    } catch (e) {
2164	      return { error: describeError(e) };
2165	    }
2166	  };
2167	  const attemptSpecs = async (): Promise<{ specs?: EndpointSpec[]; error?: string }> => {
2168	    try {
2169	      return { specs: await loadSpecsFromFile(configFile) };
2170	    } catch (e) {
2171	      return { error: describeError(e) };
2172	    }
2173	  };
2174	
2175	  // 两份输入都完整经历 读取 -> 解析 -> 严格校验；任一失败则不输出任何报告
2176	  const [snapResult, specResult] = await Promise.all([attemptSnapshot(), attemptSpecs()]);
2177	  let failed = false;
2178	  if (snapResult.error !== undefined) {
2179	    process.stderr.write(`${APP_NAME}: verify 请求快照：${snapResult.error}\n`);
2180	    failed = true;
2181	  }
2182	  if (specResult.error !== undefined) {
2183	    process.stderr.write(`${APP_NAME}: verify 场景配置：${specResult.error}\n`);
2184	    failed = true;
2185	  }
2186	  if (failed) {
2187	    process.exit(2);
2188	  }
2189	
2190	  const report = verifyRequests(
2191	    snapResult.requests as SnapshotRequest[],
2192	    specResult.specs as EndpointSpec[],
2193	    requestsFile,
2194	    configFile,
2195	  );
2196	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
2197	  process.exit(report.rejected === 0 ? 0 : 1);
2198	}
