2219	function triggerReload(): Promise<ReloadResult> {
2220	  const job = reloadChain.then(async (): Promise<ReloadResult> => {
2221	    try {
2222	      // 校验通过前只构造局部变量，任何失败都不会触碰 activeState
2223	      const next = await loadStateFromFile(configFile, activeState.version + 1);
2224	      activeState = next; // 单次同步赋值：请求不可能看到混合配置
2225	      return { ok: true, version: activeState.version };
2226	    } catch (e) {
2227	      // 不修改配置/版本，不重置序列；旧场景的正常消费继续
2228	      return { ok: false, version: activeState.version, error: describeError(e) };
2229	    }
2230	  });
2231	  // 失败也不能打断后续 reload 的排队
2232	  reloadChain = job.then(
2233	    () => undefined,
2234	    () => undefined,
2235	  );
2236	  return job;
2237	}
