2239	function writeResponse(
2240	  res: http.ServerResponse,
2241	  status: number,
2242	  headers: { readonly [name: string]: string },
2243	  body: string,
2244	): void {
2245	  try {
2246	    res.writeHead(status, headers);
2247	    res.end(body === '' ? undefined : body);
2248	  } catch {
2249	    // 预留之后客户端可能已断开：响应仍计为已消费，发送失败仅静默忽略
2250	  }
2251	}
