2253	function versionHeaders(
2254	  version: number,
2255	  extra?: { readonly [name: string]: string },
2256	): { [name: string]: string } {
2257	  // 无原型对象：配置中名为 "__proto__" 的响应头在合并时不丢失
2258	  const headers: { [name: string]: string } = Object.create(null);
2259	  headers[VERSION_HEADER] = String(version);
2260	  if (extra) {
2261	    for (const [name, value] of Object.entries(extra)) {
2262	      headers[name] = value;
2263	    }
2264	  }
2265	  return headers;
2266	}
