2288	// ---------------------------------------------------------------------------
2289	// 计划响应快照与写出跟踪
2290	// ---------------------------------------------------------------------------
2291	//
2292	// 业务/框架响应在“请求完整接收”那一刻就构造为一份计划快照：
2293	// 记录中保存的状态/应用层头/正文与随后真正写上线的字节共用同一份数据，
2294	// reload 不影响在途请求（它持有的是快照而非当前配置）。
2295	
2296	function freezeHeaders(headers: { [name: string]: string }): { readonly [name: string]: string } {
2297	  return Object.freeze(headers);
2298	}
2299	
2300	// 场景响应的应用层头：配置头 + 服务器填写的准确版本头（+ 必要时的默认 Content-Type）。
2301	// 不含 Content-Length/Connection/Date/Transfer-Encoding 等传输层自动头。
2302	function buildSceneHeaders(
2303	  item: ResponseSpec,
2304	  version: number,
2305	): { readonly [name: string]: string } {
2306	  const headers = versionHeaders(version);
2307	  let contentTypeSet = false;
2308	  for (const [name, value] of Object.entries(item.headers)) {
2309	    const lower = name.toLowerCase();
2310	    // 版本头由服务器填写且必须唯一准确：配置中的同名头（含大小写变体）可加载，发送时忽略其值
2311	    if (lower === VERSION_HEADER.toLowerCase()) {
2312	      continue;
2313	    }
2314	    if (lower === 'content-type') {
2315	      contentTypeSet = true;
2316	    }
2317	    headers[name] = value;
2318	  }
2319	  // 文本正文的默认内容类型；配置显式给出时不覆盖
2320	  if (!contentTypeSet && item.body !== '') {
2321	    headers['Content-Type'] = 'text/plain; charset=utf-8';
2322	  }
2323	  return freezeHeaders(headers);
2324	}
