2349	// 按计划快照写出；writeHead/end 在已断开套接字上抛错时标记为中断（消费已成立）。
2350	function writePlanned(
2351	  res: http.ServerResponse,
2352	  planned: PlannedResponseSnapshot,
2353	  recordId: number,
2354	): void {
2355	  try {
2356	    res.writeHead(planned.status, { ...planned.headers });
2357	    res.end(planned.body === '' ? undefined : planned.body);
2358	  } catch {
2359	    requestLog.markDelivered(recordId, 'interrupted');
2360	  }
2361	}
