2363	// 挂载一次写出生命周期跟踪。每个被记录的请求恰好回复一次，故在接收完成后立即挂载：
2364	// 延迟期间断开也能标为中断；'sent' 为终态，随后连接正常关闭不回退。
2365	function attachDeliveryTracking(res: http.ServerResponse, recordId: number): void {
2366	  let settled = false;
2367	  const settle = (status: DeliveryStatus): void => {
2368	    if (settled) {
2369	      return;
2370	    }
2371	    settled = true;
2372	    requestLog.markDelivered(recordId, status);
2373	  };
2374	  res.once('finish', () => settle('sent'));
2375	  res.once('close', () => settle(res.writableFinished ? 'sent' : 'interrupted'));
2376	  res.once('error', () => settle('interrupted'));
2377	}
2378	
2379	// 延迟结束才按接收时的计划快照发送；即便客户端提前断开也继续计时（消费在预留时已成立）
2380	function schedulePlannedResponse(
2381	  res: http.ServerResponse,
2382	  planned: PlannedResponseSnapshot,
2383	  delay: number,
2384	  recordId: number,
2385	): void {
2386	  const timer = setTimeout(() => {
2387	    pendingTimers.delete(timer);
2388	    writePlanned(res, planned, recordId);
2389	  }, delay);
2390	  pendingTimers.add(timer);
2391	}
