2393	type BodyOutcome = 'received' | 'aborted' | 'too-large';
2394	
2395	interface ReceivedBody {
2396	  readonly outcome: BodyOutcome;
2397	  // 仅在 outcome 为 'received' 时有意义（完整请求体）
2398	  readonly body: Buffer;
2399	}
2400	
2401	// 完整接收请求体；未完整接收即断开返回 'aborted'（调用方不得推进序列）
2402	function receiveBody(req: http.IncomingMessage, res: http.ServerResponse): Promise<ReceivedBody> {
2403	  return new Promise((resolve) => {
2404	    let settled = false;
2405	    let size = 0;
2406	    const chunks: Buffer[] = [];
2407	    const finish = (outcome: BodyOutcome): void => {
2408	      if (!settled) {
2409	        settled = true;
2410	        resolve({ outcome, body: outcome === 'received' ? Buffer.concat(chunks) : Buffer.alloc(0) });
2411	      }
2412	    };
2413	    req.on('data', (chunk: Buffer) => {
2414	      size += chunk.byteLength;
2415	      if (size > MAX_BODY_BYTES) {
2416	        finish('too-large');
2417	        writeResponse(
2418	          res,
2419	          413,
2420	          versionHeaders(activeState.version, {
2421	            'Content-Type': 'text/plain; charset=utf-8',
2422	          }),
2423	          'payload too large\n',
2424	        );
2425	        // 等 413 刷出后再断开，避免客户端收不到响应
2426	        res.once('finish', () => req.socket.destroy());
2427	        return;
2428	      }
2429	      chunks.push(chunk);
2430	    });
2431	    req.on('end', () => finish('received'));
2432	    req.on('error', () => finish('aborted'));
2433	    req.on('aborted', () => finish('aborted'));
2434	    res.on('close', () => finish('aborted'));
2435	  });
2436	}
