2438	async function dispatch(
2439	  req: http.IncomingMessage,
2440	  res: http.ServerResponse,
2441	): Promise<void> {
2442	  res.on('error', () => {
2443	    // 写已销毁套接字等错误无需让进程崩溃
2444	  });
2445	
2446	  const method = String(req.method);
2447	  const target = String(req.url ?? '/'); // 含查询串的原始请求目标
2448	  const pathname = target.split('?')[0]; // 查询串不参与匹配
2449	
2450	  const { outcome, body } = await receiveBody(req, res);
2451	  if (outcome !== 'received') {
2452	    // aborted：未完整接收，不匹配、不预留、不推进任何序列，也不创建记录
2453	    // too-large：已回复 413，不创建记录、不消费序列
2454	    return;
2455	  }
2456	
2457	  // 管理范围：/__contractlab 本身及 /__contractlab/ 前缀。
2458	  // 其中所有请求都不记录、不消费业务序列（含未知子路径的 404）。
2459	  if (pathname === ADMIN_BASE || pathname.startsWith(ADMIN_PREFIX)) {
2460	    await handleAdmin(method, pathname, res);
2461	    return;
2462	  }
2463	
2464	  // 完整接收且不在管理范围：此刻创建记录并取得进程内递增编号。
2465	  // 编号只取决于完整接收顺序，与接口序列的消费位置互不相关。
2466	  const state = activeState;
2467	  const record = requestLog.create({
2468	    method,
2469	    target,
2470	    path: pathname,
2471	    rawHeaders: req.rawHeaders,
2472	    body,
2473	    configVersion: state.version,
2474	  });
2475	  attachDeliveryTracking(res, record.id);
2476	
2477	  // 业务匹配：在本次同步执行内抓取状态快照，预留后与后续 reload 互不影响
2478	  const endpoint =
2479	    method === 'GET' || method === 'POST'
2480	      ? state.endpoints.get(`${method} ${pathname}`)
2481	      : undefined;
2482	
2483	  if (!endpoint) {
2484	    // 未匹配请求：404，不消费、无消费位置
2485	    record.matched = false;
2486	    record.endpoint = `${method} ${pathname}`;
2487	    const planned = buildFrameworkPlanned(
2488	      404,
2489	      state.version,
2490	      'not found\n',
2491	      'text/plain; charset=utf-8',
2492	    );
2493	    record.plannedResponse = planned;
2494	    writePlanned(res, planned, record.id);
2495	    return;
2496	  }
2497	  record.matched = true;
2498	  record.endpoint = endpoint.key;
2499	
2500	  // 正文结构规则（如有）：校验失败返回 400 差异报告，不发送场景响应、不消费序列。
2501	  // 规则、序列与版本均取自上面同一快照 state。
2502	  if (endpoint.bodyRule) {
2503	    const report = validateBodyWithContentType(
2504	      req.headers['content-type'],
2505	      body,
2506	      endpoint.bodyRule,
2507	    );
2508	    if (report) {
2509	      record.bodyValidationPassed = false;
2510	      record.bodyRejection = report;
2511	      const planned = buildFrameworkPlanned(
2512	        400,
2513	        state.version,
2514	        `${JSON.stringify(report)}\n`,
2515	        'application/json; charset=utf-8',
2516	      );
2517	      record.plannedResponse = planned;
2518	      writePlanned(res, planned, record.id);
2519	      return;
2520	    }
2521	    record.bodyValidationPassed = true;
2522	  }
2523	
2524	  // 校验通过（或无规则）：立即预留，并把消费位置与场景计划响应记入同一条记录
2525	  const { position, item } = reserveNext(endpoint);
2526	  record.sequencePosition = position;
2527	  record.sequenceLength = endpoint.responses.length;
2528	  const planned = buildScenePlanned(item, state.version);
2529	  record.plannedResponse = planned;
2530	  schedulePlannedResponse(res, planned, item.delay, record.id);
2531	}
