2547	async function handleAdmin(method: string, pathname: string, res: http.ServerResponse): Promise<void> {
2548	  if (pathname === HEALTH_PATH) {
2549	    if (method === 'GET') {
2550	      sendJson(res, 200, { status: 'ok', version: activeState.version }, activeState.version);
2551	    } else {
2552	      sendNotFound(res);
2553	    }
2554	    return;
2555	  }
2556	
2557	  if (pathname === RELOAD_PATH) {
2558	    if (method === 'POST') {
2559	      const result = await triggerReload();
2560	      sendJson(res, 200, result, result.version);
2561	    } else {
2562	      sendNotFound(res);
2563	    }
2564	    return;
2565	  }
2566	
2567	  if (pathname === REQUESTS_PATH) {
2568	    if (method === 'GET') {
2569	      const records = requestLog.snapshot();
2570	      sendJson(
2571	        res,
2572	        200,
2573	        { note: requestsUsageNote(), count: records.length, records },
2574	        activeState.version,
2575	      );
2576	    } else {
2577	      sendNotFound(res);
2578	    }
2579	    return;
2580	  }
2581	
2582	  if (pathname === REQUESTS_CLEAR_PATH) {
2583	    if (method === 'POST') {
2584	      const removed = requestLog.clear();
2585	      sendJson(
2586	        res,
2587	        200,
2588	        { ok: true, removed, note: requestsUsageNote() },
2589	        activeState.version,
2590	      );
2591	    } else {
2592	      sendNotFound(res);
2593	    }
2594	    return;
2595	  }
2596	
2597	  // 管理范围内的未知路径：仍是管理请求，不记录、不消费
2598	  sendNotFound(res);
2599	}
