2605	function shutdown(): void {
2606	  if (shuttingDown) {
2607	    return;
2608	  }
2609	  shuttingDown = true;
2610	  // 取消所有尚未发出的延迟响应
2611	  for (const timer of pendingTimers) {
2612	    clearTimeout(timer);
2613	  }
2614	  pendingTimers.clear();
2615	  // 关闭监听并断开空闲/在途连接，随后正常退出（退出码 0）
2616	  try {
2617	    server.closeAllConnections();
2618	  } catch {
2619	    // 旧版本兜底：忽略，下面的 close/超时仍会结束进程
2620	  }
2621	  server.close(() => process.exit(0));
2622	  setTimeout(() => process.exit(0), 2000).unref();
2623	}
