2625	async function startServer(configArg: string, port: number): Promise<void> {
2626	  configFile = path.resolve(configArg);
2627	
2628	  // 先读配置：配置无效时根本不会创建监听
2629	  activeState = await loadStateFromFile(configFile, 1);
2630	
2631	  server = http.createServer((req, res) => {
2632	    dispatch(req, res).catch(() => {
2633	      try {
2634	        req.socket.destroy();
2635	      } catch {
2636	        // 套接字可能已销毁
2637	      }
2638	    });
2639	  });
2640	
2641	  await new Promise<void>((resolve, reject) => {
2642	    server.once('error', reject);
2643	    // 仅监听本机回环地址
2644	    server.listen(port, '127.0.0.1', resolve);
2645	  });
2646	
2647	  const address = server.address();
2648	  const actualPort = typeof address === 'object' && address ? address.port : port;
2649	  process.stdout.write(
2650	    `${APP_NAME}: listening on http://127.0.0.1:${actualPort}\n` +
2651	      `${APP_NAME}: config ${configFile} (version 1, ${activeState.endpoints.size} endpoints)\n`,
2652	  );
2653	
2654	  const onSignal = (): void => shutdown();
2655	  process.on('SIGINT', onSignal);
2656	  process.on('SIGTERM', onSignal);
