```ts
// 重放时剥离的头：原 Host / Expect / 逐跳与分帧头（含 Connection 指名的头）
const REPLAY_STRIP_HEADERS: ReadonlySet<string> = new Set([
  'host', 'expect', 'connection', 'keep-alive', 'content-length',
  'transfer-encoding', 'te', 'trailer', 'upgrade',
  'proxy-authenticate', 'proxy-authorization',
]);

function filterReplayHeaders(rawHeaders, where): [string, string][] {
  const named = new Set<string>();
  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
    if (rawHeaders[j].toLowerCase() === 'connection') {
      for (const token of rawHeaders[j+1].split(',')) {
        const t = token.trim().toLowerCase();
        if (t !== '') named.add(t);
      }
    }
  }
  const out: [string, string][] = [];
  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
    const name = rawHeaders[j]; const value = rawHeaders[j+1];
    const lower = name.toLowerCase();
    if (REPLAY_STRIP_HEADERS.has(lower) || named.has(lower)) continue;
    const hWhere = `${where}[${j}]`;
    if (!HEADER_NAME_RE.test(name)) snapshotFail(hWhere, `...不是可发送的 HTTP 头名称`);
    for (value chars) same rule as config: (code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff → fail
    out.push([name, value]);
  }
  return out;
}
