Replay engine:

```ts
interface ReplayResponse {
  readonly status: number;
  readonly body: Buffer;
}

type ReplayExchange =
  | { readonly ok: true; readonly response: ReplayResponse }
  | { readonly ok: false; readonly reason: string };

function replayOne(port: number, request: ReplayRequest, timeoutMs: number): Promise<ReplayExchange> {
  return new Promise((resolve) => {
    let settled = false;
    const done = (outcome: ReplayExchange): void => {
      if (!settled) { settled = true; clearTimeout(timer); resolve(outcome); }
    };

    // 业务头在前（原顺序/大小写/重复项），随后按目标与实际字节数重建
    // Host 与 Content-Length；每条请求独立连接，完成后关闭。
    const headers: string[] = [];
    for (const [name, value] of request.headers) headers.push(name, value);
    headers.push('Host', `127.0.0.1:${port}`);
    headers.push('Content-Length', String(request.body.byteLength));
    headers.push('Connection', 'close');

    const req = http.request({
      host: '127.0.0.1',
      port,
      method: request.method,
      path: request.target, // 原样：保留查询串与百分号编码，不归一化
      headers,
      agent: false,       // 不连接池化：一次一条，每条只尝试一次
    });

    // 总超时：从开始连接覆盖完整收发，持续来数据不延长
    const timer = setTimeout(() => {
      req.destroy();
      done({ ok: false, reason: `超过总超时 ${timeoutMs}ms（自开始连接覆盖完整收发）` });
    }, timeoutMs);

    req.on('response', (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer) => chunks.push(chunk));
      res.on('end', () => {
        done({ ok: true, response: { status: res.statusCode ?? 0, body: Buffer.concat(chunks) } });
      });
      res.on('aborted', () => done({ ok: false, reason: '响应中途断开（部分响应不算完整）' }));
      res.on('error', (e) => done({ ok: false, reason: `响应读取失败：${describeError(e)}` }));
      res.on('close', () => {
        if (!res.complete) done({ ok: false, reason: '响应中途断开（部分响应不算完整）' });
      });
    });
    req.on('error', (e: Error) => {
      done({ ok: false, reason: `通信失败：${e.message}` });
    });
    req.end(request.body);
  });
}
```

